from lib import *

# ===== INSERT A : after Principle 1 proof-of-limits slide
slide("Principle 1 · Consent", "Two more grounds inside consent: equivalence and uncertainty",
'''<div class="cols"><div class="col"><div class="label">Equivalence in exchange</div><ul class="b small">
<li>A sale swaps two counter-values. The shortfall formula measures how far they have come apart.</li>
<li>The jurists do <b>not</b> demand exact equality. A small disparity (<i class="t">gabn-i yesîr</i>) does not touch the contract; a gross one (<i class="t">gabn-i fâhiş</i>) is judged by the custom of that trade.</li>
<li>Hanafīs and Shāfiʿīs give the buyer an option to rescind for gross disparity <b>only where there is deceit</b> (<i class="t">taghrīr</i>), as Mecelle 356 follows. Mālikīs, Ḥanbalīs and others give it even without deceit.</li>
<li>All agree that a buyer who knowingly accepts the disparity cannot rescind.</li></ul>
<div class="bar" style="font-size:21px;margin-top:10px"><b>Here the strictest school is met:</b> the disparity is hidden, which is deceit. The claim also needs the shortfall to be material, so a trivial gap is outside it.</div></div>
<div class="col"><div class="label">Uncertainty (<i>gharar</i>)</div><ul class="b small">
<li>The Prophet forbade a sale that contains <i>gharar</i>, uncertainty about what is being sold (Sahih Muslim 1513, Abū Hurayra).</li>
<li>Classical <i>gharar</i> is uncertainty about the subject itself: existence, amount or attribute. Light uncertainty that people tolerate does not void a sale.</li>
<li>Here the unknown attribute is the <b>life</b>, which sets the price. The seller knows it and the buyer does not. This is the lopsided form of <i>gharar</i>, which the jurists treat as <i>taghrīr</i>.</li></ul>
<p class="small">'''+chip("strong")+''' Equivalence: clear, with the school difference stated.<br>'''+chip("probable")+''' Gharar: the text is sound; fitting a one-sided hidden attribute under it is our step. We therefore do not rest N1 on it.</p></div></div>''',
"Gabn and taghrīr: TDV İslâm Ansiklopedisi, &#8220;Gabn&#8221; (page opened). Muslim 1513: wording from search summaries of tohed.com; the page itself was not opened.")

# ===== INSERT B : after Principle 2 objection slide
slide("Principle 2 · Harm", "Harm to many: small losses add up",
'''<div class="card dash"><b>Imagine</b> one baker shorting one customer by one coin. Now imagine the practice built into a million units of a product. The harm to each buyer is the same; the harm to the public is a million times the act.</div>
<div class="cols" style="margin-top:18px"><div class="col"><div class="label">The weighing, with the Mecelle&#8217;s own maxims</div><ol class="prem" style="font-size:20.5px">
<li data-n="1">If the practice is forbidden, the maker loses the <i>extra sales</i> that early failure would have brought.</li>
<li data-n="2">If it is allowed, buyers lose money already paid, and the public bears the waste and the repeated spending.</li>
<li data-n="3">A private harm is accepted to repel a public one. <span class="tiny">(art. 26)</span></li>
<li data-n="4">The heavier harm is removed by the lighter. <span class="tiny">(art. 27)</span></li>
<li class="concl" data-n="5">So the maker&#8217;s lost extra sales yield to the public&#8217;s loss.</li></ol></div>
<div class="col"><div class="label">Two checks</div><ul class="b small">
<li><b>Is the maker&#8217;s loss even a harm?</b> It is income he has not yet earned, from a sale that works only if the buyer is not told. A profit that exists only through concealment is not a protected interest (Qur&#8217;an 4:29).</li>
<li><b>Who gains, who pays?</b> Burdens go with benefits (art. 87&#8211;88). The maker takes the benefit, so he bears the cost of telling.</li>
<li>Even if his loss counted, <b>art. 31</b> asks that harm be removed as far as possible: disclosure removes the buyers&#8217; harm and still lets him sell.</li></ul>
<p class="small">'''+chip("strong")+''' The maxims are explicit; applying them to a firm against a public is by analogy.</p></div></div>''',
"Mecelle 26, 27, 31, 87, 88: Berki/Balcı text, read in full.")

# ===== INSERT C : after Principle 4 waste slide
slide("Principle 4 · Waste", "Waste and the earth: what we claim, and what we do not",
'''<div class="cols"><div class="col" style="flex:1.1"><div class="label">The record</div><ul class="b small">
<li>The Global E-waste Monitor 2024 reports <b>62 million tonnes</b> of e-waste in 2022, up 82% since 2010, and that only <b>22.3%</b> was documented as properly collected and recycled. About US$62 billion of recoverable resources went unaccounted for.</li>
<li>Among the causes it names: <i class="t">&#8220;shorter product life cycles,&#8221;</i> <i class="t">&#8220;limited repair options,&#8221;</i> and <i class="t">&#8220;design shortcomings.&#8221;</i></li>
<li>The Qur&#8217;an: <i class="t">&#8220;Do not spread corruption in the land after it has been set in order&#8221;</i> (7:56); <i class="t">&#8220;Corruption has spread on land and sea as a result of what people&#8217;s hands have done&#8221;</i> (30:41).</li></ul></div>
<div class="col"><div class="label">The argument</div><ol class="prem" style="font-size:20.5px">
<li data-n="1">A product discarded early because of a maker&#8217;s choice adds one unit to the waste stream that would not have been added then. <span class="tiny">(test of connection)</span></li>
<li data-n="2">Those who live with that stream bear its cost and never agreed to it.</li>
<li class="concl" data-n="3">That is harm to third parties (N2), and wasteful spending by buyers who must buy again.</li></ol>
<div class="bar amber" style="margin-top:12px;font-size:20px"><b>Not claimed:</b> that planned obsolescence causes any stated share of the 62 million tonnes. The report names several causes and does not measure this one. Only the direction is argued: each avoidable early discard adds to the stream.</div>
<p class="small" style="margin-top:8px">'''+chip("strong")+' direction · '+chip("support")+''' size: unmeasured. N4 stays support; the weight rides on N2.</p></div></div>''',
"UNITAR/ITU, Global E-waste Monitor 2024, press release (page opened). Qur&#8217;an 7:56 and 30:41 (Khattab, quran.com, page opened).")

# ===== INSERT D : the maker's own case, after Defense 5
slide("The maker&#8217;s own case", "The strongest version of the defense: &#8220;it funds innovation&#8221;",
'''<div class="card dash"><b>The maker says:</b> &#8220;Research costs a great deal. If products last forever, nobody buys the next one, revenue falls, research stops, and everyone loses progress. Short life is how I pay for the future.&#8221; We accept that each step <i>may</i> be true. The question is whether the conclusion follows.</div>
<table style="margin-top:16px;font-size:20px"><tr><th style="width:70px">Test</th><th>What it asks</th><th style="width:260px">Result</th></tr>
<tr><td class="k">T1</td><td>If it is a funding mechanism, why is it hidden?</td><td>Self-defeating</td></tr>
<tr><td class="k">T2</td><td>Can the same money be raised by lawful means?</td><td>Yes: concealment is not needed</td></tr>
<tr><td class="k">T3</td><td>Is the new product better, or not?</td><td>Either way the defense fails</td></tr>
<tr><td class="k">T4</td><td>Does the argument stop anywhere?</td><td>It proves too much</td></tr>
<tr><td class="k">T5</td><td>Who pays, and who gains?</td><td>The payer is not the gainer</td></tr></table>
<p class="small" style="margin-top:10px">All five rest on logic and on the Mecelle, not on forecasts of the market.</p>''')

slide("The maker&#8217;s own case", "T1 and T2: a lawful aim does not sanctify a hidden means",
'''<div class="cols"><div class="col"><div class="label">T1 · Hidden means contradict the claim</div><ol class="prem" style="font-size:20.5px">
<li data-n="1">If buyers would accept &#8220;this lasts two years and the difference funds the next model,&#8221; the maker loses nothing by saying so.</li>
<li data-n="2">He chooses silence.</li>
<li class="concl" data-n="3">So he expects refusal. A means that works only while its victims do not know is not consent (N1).</li></ol>
<p class="small" style="margin-top:10px"><b>Reply to the retort &#8220;nobody would buy then&#8221;:</b> that concedes the buyer did not agree.</p></div>
<div class="col"><div class="label">T2 · The same aim, by lawful means</div><table style="font-size:19px"><tr><th>Aim</th><th>Lawful route</th></tr>
<tr><td>Recover research cost</td><td>Say the price covers it, and price it openly</td></tr>
<tr><td>Keep sales flowing</td><td>Sell the next model on its merits; offer trade-in or upgrade plans</td></tr>
<tr><td>Serve those who want cheap and short</td><td>A budget line with the life printed</td></tr>
<tr><td>Control the device</td><td>Lease it, call it a lease, price it as rent</td></tr></table>
<p class="small" style="margin-top:10px">Necessity is measured by what it needs (art. 22), harm is removed as far as possible (art. 31), and need does not cancel another&#8217;s right (art. 33). Where a lawful route exists, concealment is not necessary.</p></div></div>
<p class="small" style="margin-top:6px">'''+chip("strong")+'''</p>''')

slide("The maker&#8217;s own case", "T3: the new product is either better or it is not",
'''<div class="cols"><div class="col"><div class="card teal"><div class="label">Case 1 · the new product is better</div><p class="small" style="margin:0">Then it gives buyers a reason to buy it. The old device&#8217;s early death is not needed to sell it. The &#8220;invention&#8221; stands on its own merit, and a sound old device is only the platform it improves on.</p></div></div>
<div class="col"><div class="card amber"><div class="label" style="color:#B25E00">Case 2 · it is not better</div><p class="small" style="margin:0">Then the buyer pays again for the same thing. The revenue funds no advance; it funds a repackaging. That is cost to the buyer with no benefit to anyone, which is <b>research in name only</b>.</p></div></div></div>
<div class="bar" style="margin-top:18px"><b>Either way the defense fails.</b> In case 1 it is unnecessary; in case 2 it is empty.</div>
<ul class="b small" style="margin-top:16px">
<li><b>The claimed link is asserted, not shown.</b> Nothing in the idea of a new model requires the old one to fail. The step from &#8220;obsolete the old&#8221; to &#8220;fund the new&#8221; is an empirical claim, and the burden of proof is on the one who claims (art. 76).</li>
<li><b>What this assumes:</b> in case 1, that demand responds to real improvement. That is plausible, not certain. If sales were lower, T1 and T2 still apply: price openly instead of hiding.</li></ul>
<p class="small">'''+chip("strong")+'''</p>''')

slide("The maker&#8217;s own case", "T4 and T5: it proves too much, and the payer is not the gainer",
'''<div class="cols"><div class="col"><div class="label">T4 · Where does the argument stop?</div><ul class="b small">
<li>If a good end licenses hidden shortfall, a baker may thin his flour to fund a better oven. A builder may skimp the concrete to fund research.</li>
<li>Any unagreed charge could be justified this way, by naming a worthy use for the money.</li>
<li>But taking another&#8217;s wealth without lawful cause is not allowed (art. 97; Qur&#8217;an 4:29). The worth of the use does not change how it was taken.</li></ul></div>
<div class="col"><div class="label">T5 · Costs follow benefits</div><ul class="b small">
<li>Burdens go with benefits (art. 87&#8211;88).</li>
<li>The buyer pays the hidden cost, then pays again for the new model. The maker gets the funding and the new sale.</li>
<li>If research benefits all, all should fund it openly. It cannot be charged to one class of buyer by concealment.</li></ul></div></div>
<div class="bar amber" style="margin-top:18px"><b>Verdict on the maker&#8217;s case.</b> Defense 5 and the funding claim fail T1 to T5. What survives is narrower: a maker may charge openly for research, may end support with notice, and may sell short-lived products honestly described.</div>
<p class="small" style="margin-top:8px">'''+chip("strong")+'''</p>''')

slide("The maker&#8217;s own case", "Three hypotheses we state but do not need",
'''<p class="small">Some claims favor the ruling but cannot be proved from the armchair. We say them plainly and mark them, so the proof does not lean on them.</p>
<table style="font-size:20px"><tr><th style="width:56px">#</th><th>Hypothesis</th><th style="width:300px">Why we cannot call it a fact</th></tr>
<tr><td class="k">H1</td><td>Where a maker earns by real advances rather than by forced replacement, he gains a durable market and the means to fund research.</td><td>A claim about firms. It varies by industry and has not been measured here.</td></tr>
<tr><td class="k">H2</td><td>A buyer who is not made to replace sound devices has more money for genuinely better ones.</td><td>Depends on what buyers do with the savings.</td></tr>
<tr><td class="k">H3</td><td>Technology advances faster when sales rest on improvement rather than on early failure.</td><td>An empirical claim about the whole economy. We state no figure for it.</td></tr></table>
<div class="bar" style="margin-top:18px;font-size:22px"><b>Why this is not a retreat.</b> The ruling stands on consent, harm and ownership. If H1 to H3 are true, they add weight. If they are false, T1 to T5 still defeat the funding defense, because that defense claims a license to hide, not merely a benefit.</div>
<p class="small" style="margin-top:8px">'''+chip("support")+'''</p>''')

# ===== INSERT E : doubt court 7
def qa(q, a, v): return '<div class="qa"><span class="qq">%s</span> %s<br>%s</div>' % (q, '<span class="verdict">%s</span>' % v, a)
slide("The doubt court · 7 of 7", "Doubts about innovation, price and waste",
 qa("25 · &#8220;Without forced replacement, research budgets will shrink.&#8221;", "Possibly for some makers, and the ruling does not forbid raising price openly or selling better models. Funding by concealment is the only thing removed (T1&#8211;T2).", chip("part")) +
 qa("26 · &#8220;Durable products cost more. Buyers are harmed by higher prices.&#8221;", "The ruling does not require durability. A cheap short-lived product, stated as such, is lawful (doubt 1). A higher price that buyers see and accept is consent.", chip("no")) +
 qa("27 · &#8220;Is e-waste mostly caused by planned obsolescence?&#8221;", "Not claimed. The report names several causes and does not measure this one. The argument is about direction: each avoidable early discard adds to the stream.", chip("out")) +
 qa("28 · &#8220;If the new model is truly better, why hide anything?&#8221;", "Exactly the point of T3. A better model needs no hidden failure to sell it. A model that does is not better.", chip("yes")))
